[asy]
draw((0,0)--(8,0)--(8,18)--(2.5,20)--(0,12)--cycle);
label("8''",(1.3,16),NW);
label("6''",(5.2,19),NE);
label("18''",(8,9),E);
label("8''",(4,0),S);
